package com.aicharacter.v3;
/** Enforces a coupled kinetic chain: requested pose is clipped by mobility and feeds stress back into muscle capacity. */
public final class JointConstraintEngine{private JointConstraintEngine(){}
 public static void solve(WorldState s){if(s==null||s.bodyRig==null)return;if(s.joints==null)s.joints=new JointConstraintState();JointConstraintState j=s.joints;BodyRigState r=s.bodyRig;double mobility=s.musculoskeletal==null?1:s.musculoskeletal.jointMobility;double wave=Math.sin(r.stridePhase*Math.PI*2),gait=s.girlTravel!=null&&s.girlTravel.active?Math.min(1,s.girlTravel.lastSpeed/92.0):0;double hip=wave*.72*gait,knee=Math.max(0,-wave)*.82*gait,ankle=-wave*.48*gait,spine=r.spineLean/.18,shoulder=r.shoulderCounter/.18;double requestedNeck=r.headStabilization/.12;double anatomicalNeckLimit=.38*mobility;double neck=Math.max(-anatomicalNeckLimit,Math.min(anatomicalNeckLimit,requestedNeck));j.hip=clip(hip,mobility);j.knee=clip(knee,mobility);j.ankle=clip(ankle,mobility);j.spine=clip(spine,mobility);j.shoulder=clip(shoulder,mobility);j.neck=clip(neck,mobility);double demand=maxAbs(hip,knee,ankle,spine,shoulder,neck);j.limitStress=Math.max(0,Math.min(1,(demand-Math.max(.25,mobility))/.55));if(s.musculoskeletal!=null){s.musculoskeletal.legForceCapacity=Math.max(.28,s.musculoskeletal.legForceCapacity*(1-j.limitStress*.12));s.musculoskeletal.coreForceCapacity=Math.max(.30,s.musculoskeletal.coreForceCapacity*(1-j.limitStress*.08));}}
 private static double clip(double v,double m){double lim=Math.max(.25,Math.min(1,m));return Math.max(-lim,Math.min(lim,v));}private static double maxAbs(double...v){double m=0;for(double x:v)m=Math.max(m,Math.abs(x));return m;}
}